namespace Synkoz {static class WindowControllerR12 {static readonly Dictionary<Form,EffectsForm936> editors=new Dictionary<Form,EffectsForm936>();public static void Register(Form window,EffectsForm936 editor){editors[window]=editor;window.FormClosed+=delegate{editors.Remove(window);};}public static bool Dispatch(string command,int key,int delta,Form main){return DispatchToR12(Form.ActiveForm,command,key,delta,main);}internal static bool DispatchToR12(Form active,string command,int key,int delta,Form main){if(active==null||active==main)return active==null;EffectsForm936 editor;if(!editors.TryGetValue(active,out editor))editor=active as EffectsForm936;if(editor!=null){if(command=="KY")editor.ControllerTurn940(key,delta);else if(command=="UNDO")editor.ControllerUndo940();return true;}if(command=="KY"){var controls=All(active).Where(c=>c.Visible&&c.Enabled&&(c is TrackBar||c is NumericUpDown||c is ComboBox)).ToArray();if(key>=0&&key<controls.Length){var control=controls[key];var n=control as NumericUpDown;var t=control as TrackBar;var c=control as ComboBox;if(n!=null)n.Value=Math.Max(n.Minimum,Math.Min(n.Maximum,n.Value+delta*n.Increment));if(t!=null)t.Value=Math.Max(t.Minimum,Math.Min(t.Maximum,t.Value+delta));if(c!=null)c.SelectedIndex=Math.Max(0,Math.Min(c.Items.Count-1,c.SelectedIndex+delta));}}return true;}static IEnumerable<Control> All(Control root){foreach(Control c in root.Controls){yield return c;foreach(var x in All(c))yield return x;}}}}
